import {
	type BootDevServerMutationVariables,
	useSubscribeToDevServerUpdatesSubscription
} from '@/generated/graphql'
import { SandboxEnvironment, getDevServerId } from '@/utils/sandbox'
import { useCallback, useEffect } from 'react'
import { useThrottledBootDevServer } from './useThrottledBootDevServer'

/**
 * Returns the proxy URL for the dev server.
 * Prefers the project group revision ID if set over the project group ID.
 */
export const getDevServerProxyUrl = ({
	projectGroupId,
	projectGroupRevisionId,
	server,
	pathname = '/'
}: {
	projectGroupId: string | null
	projectGroupRevisionId: string | null
	server: 'web' | 'mobile'
	/**
	 * The pathname to append to the URL. Must start with a '/'.
	 * Defaults to '/' if not provided.
	 */
	pathname: string | null
}) => {
	const protocol = process.env.EXPO_PUBLIC_DEV_SERVER_DOMAIN?.includes(
		'localhost'
	)
		? 'http'
		: 'https'
	const domain = [
		...(projectGroupRevisionId
			? [projectGroupRevisionId, 'revision']
			: [projectGroupId]),
		server,
		process.env.EXPO_PUBLIC_DEV_SERVER_DOMAIN!
	].join(
		process.env.EXPO_PUBLIC_DEV_SERVER_DOMAIN?.endsWith('.ngrok.app')
			? '-'
			: '.'
	)
	return `${protocol}://${domain}${
		!pathname || pathname === '/' ? '' : pathname
	}`
}

export interface DevServerUrls {
	web: string
	mobile: string
}

interface UseDevServerUrlParams {
	projectGroupId: string
	isFileBased: boolean
}

export function useDevServerUrls({
	projectGroupId,
	isFileBased
}: UseDevServerUrlParams): DevServerUrls | null {
	const bootDevServer = useThrottledBootDevServer()

	const boot = useCallback(
		async (input: BootDevServerMutationVariables['input']) => {
			const result = await bootDevServer({
				input
			})
			const bootDevServerResult = result?.data?.bootDevServer.devServerSession
			if (!bootDevServerResult) {
				return
			}

			return bootDevServerResult
		},
		[bootDevServer]
	)

	useEffect(() => {
		if (!isFileBased) {
			return
		}
		const input = {
			projectGroupId
		}
		boot(input)
	}, [boot, projectGroupId, isFileBased])

	const devServerId = getDevServerId({
		projectGroupId,
		projectGroupRevisionId: null,
		environment: SandboxEnvironment.BUILDER
	})
	useSubscribeToDevServerUpdatesSubscription({
		skip: !isFileBased,
		variables: {
			id: devServerId
		}
	})

	if (!isFileBased) {
		return null
	}

	return {
		web: getDevServerProxyUrl({
			projectGroupId,
			projectGroupRevisionId: null,
			server: 'web',
			pathname: null
		}),
		mobile: getDevServerProxyUrl({
			projectGroupId,
			projectGroupRevisionId: null,
			server: 'mobile',
			pathname: null
		})
	}
}
